package com.medicine.reminder.controller; import com.medicine.reminder.dto.*; import com.medicine.reminder.model.*; import com.medicine.reminder.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/medicines") public class MedicineController {private final MedicineService s;public MedicineController(MedicineService x){s=x;}private Long u(Authentication a){return(Long)a.getDetails();}@GetMapping public List<Medicine> list(@RequestParam Long profileId,Authentication a){return s.list(profileId,u(a));}@PostMapping public Medicine create(@Valid @RequestBody MedicineDTO d,Authentication a){return s.create(d,u(a));}@PutMapping("/{id}") public Medicine update(@PathVariable Long id,@Valid @RequestBody MedicineDTO d,Authentication a){return s.update(id,d,u(a));}@PostMapping("/{id}/refill") public Medicine refill(@PathVariable Long id,@RequestBody Map<String,Integer> body,Authentication a){return s.refillStock(id,body.getOrDefault("quantity",0),u(a));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,Authentication a){s.delete(id,u(a));}}
